INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63686586', 63686586, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'POLITEKNIK KESEHATAN JAMBI', 'Jasa Outsourching Satpam, Pengemudi dan Petugas Kebersihan', 'Jasa Lainnya', 'E-Purchasing', 'Jambi, Jambi (Kota)', 2833983000, 'December 2025', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 THN', 'Pengadaaan Jasa Outsourching Satpam, Pengemudi dan Petugas Kebersihan', 'A. Ruang lingkup pekerjaan Pengadaan Jasa Security terdiri dari: 1. Melaksanakan patroli pengamanan dilingkungan kantor/kampus sesuai dengan lokasi yang ditentukan serta melakukan rekam laporan hasil patroli setiap 2 jam pada buku kendali laporan; 2. Melaksanakan pengamanan orang/civitas akademika maupun masyarakat/stakeholder, sarana dan prasarana yang berada dilokasi kantor/kampus Poltekkes Kemenkes Jambi; 3. Membantu pelaksanaan menyalakan dan mematikan lampu-lampu penerangan serta peralatan yang menggunakan listrik pada ruang-ruang perkantoran sesuai kebutuhan jam kerja serta berkoordinasi dengan pengguna gedung dan lingkungan Poltekkes Kemenkes Jambi; 4. Membantu dengan melaporkan terkait kondisi penerangan, sistem pengaman, yang mengalami gangguan/tidak normal pada Bagian Rumah Tangga; 5. Melakukan koordinasi dengan bagian Rumah Tangga/Perlengkapan Poltekkes Kemenkes Jambi apabila terjadi permasalahan yang timbul akibat padamnya listrik PLN; 6. Melaksanakan pengamanan/pengawalan kegiatan-kegiatan tertentu diluar kantor (seperti : pengambilan uang ke Bank oleh Bendahara); 7. Melaksankan pengaturan masuk keluarnya kendaraan dari dan ke wilayah Poltekkes Kemenkes Jambi, termasuk membantu pengaturan menyeberang jalan pegawai dan mahasiswa/masyarakat; 8. Mengetahui posisi penempatan dan mampu menggunakan alat pemadam kebakaran (APAR) bila terjadi kebakaran; 9. Tenaga keamanan memiliki sertifikat garda pratama yang dikeluarkan dari Kepolisian Republik Indonesia; B. Ruang lingkup pekerjaan Pengadaan Jasa Tenaga Kebersihan terdiri dari: 1. Dalam Gedung (Membersihkan debu, Pel Basah/Kering, Menyapu) a.) Semua fasilitas kantor dan furniture; b.) Lobby dan seluruh bagian ruang kantor; c.) Jendela dan pintu kaca setiap ruangan kantor; d.) Ruang kelas, perpustakaan dan laboratorium; e.) Toilet Dosen, Mahasiswa dan dapur/ Pantry; f.) Tempat ibadah, ruang rapat/pertemuan dan ruang lainnya yang terdapat didalam gedung, serta; g.) Sisi luar/teras depan, belakang dan samping ruangan serta kaca gedung; 2. Luar Gedung a.) Perawatan dan pemeliharaan halaman, serta menjaga kebersihan area parkir, saluran pembuangan air/gorong-gorong, dan taman dilingkungan Kantor/kampus Poltekkes Kemenkes Jambi; b.) Pemotongan/ Penyemprotan rumput dilakukan setiap bulan. C. Ruang lingkup pekerjaan Pengadaan Jasa Tenaga Driver terdiri dari: 1. Menjaga kebersihan dan perawatan mobil baik interior maupun eksterior; 2. Mendata dan melakukan perawatan/service berkala kendaraan operasional selanjutnya pembiayaan service/perawatan dibebankan pada DIPA-Poltekkes Kemenkes Jambi; 3. Memobilisasi/pengantaran/penjemputan kendaraan jabatan (Direktur) dan kendaraan operasional untuk menunjang kegiatan PBM dan operasional kantor,; 4. Mendata dan melakukan pembayaran pajak berkala kendaraan operasional selanjutnya pembiayaan service/perawatan dibebankan pada DIPA-Poltekkes Kemenkes Jambi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1107762);
